"""Tables of the Italian and Turkish device front-ends (runtime/src/vtts_text_it_tables.h,
vtts_text_tr_tables.h), generated from the Python sources (src/vtts/frontend/it, tr, latin.py,
latin_norm.py, lexicons/it, lexicons/tr). Called by gen_text_tables.py."""

from __future__ import annotations

from pathlib import Path

SRC = Path(__file__).resolve().parents[1] / "src"
HEAD = ["/* SPDX-License-Identifier: Apache-2.0 */",
        "/* generated by runtime/tools/gen_text_tables.py -- do not edit */"]


def c_str(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def c_list(name: str, items) -> list[str]:
    items = list(items)
    if not items:
        return [f"static const char *const {name}[1] = {{0}};", f"#define {name}_N 0", ""]
    out = [f"static const char *const {name}[{len(items)}] = {{"]
    out += ["    " + ", ".join(c_str(s) for s in items[i:i + 6]) + "," for i in range(0, len(items), 6)]
    return out + ["};", f"#define {name}_N {len(items)}", ""]


def c_pairs(name: str, items) -> list[str]:
    items = list(items)
    out = [f"static const char *const {name}[{max(len(items), 1)}][2] = {{"]
    out += [f"    {{{c_str(a)}, {c_str(b)}}}," for a, b in items] or ["    {0, 0},"]
    return out + ["};", f"#define {name}_N {len(items)}", ""]


def c_triples(name: str, items) -> list[str]:
    out = [f"static const char *const {name}[{len(items)}][3] = {{"]
    out += [f"    {{{c_str(a)}, {c_str(b)}, {c_str(c)}}}," for a, b, c in items]
    return out + ["};", f"#define {name}_N {len(items)}", ""]


def c_letters(name: str, items) -> list[str]:
    """(code point, UTF-8 string) pairs."""
    items = list(items)
    out = [f"static const struct {{ uint32_t cp; const char *s; }} {name}[{len(items)}] = {{"]
    out += [f"    {{0x{ord(k):04X}, {c_str(v)}}}," for k, v in items]
    return out + ["};", f"#define {name}_N {len(items)}", ""]


def fold_runs(name: str, fold) -> list[str]:
    """fold() of every code point >= 0x80 as runs (start, count, first result, step 0/1); results
    are single code points (any size)."""
    folded = [(c, fold(chr(c))) for c in range(0x80, 0x110000) if not 0xD800 <= c < 0xE000]
    folded = [(c, f) for c, f in folded if f]
    assert all(len(f) == 1 for _, f in folded)
    runs: list[list[int]] = []
    for c, f in folded:
        if runs and c == runs[-1][0] + runs[-1][1] and runs[-1][1] < 65535:
            r = runs[-1]
            if r[1] == 1 and ord(f) in (r[2], r[2] + 1):
                r[1], r[3] = 2, ord(f) - r[2]
                continue
            if r[1] > 1 and ord(f) == r[2] + r[1] * r[3]:
                r[1] += 1
                continue
        runs.append([c, 1, ord(f), 0])
    out = [f"static const struct {{ uint32_t start; uint16_t count; uint8_t step; uint32_t first; }} {name}[{len(runs)}] = {{"]
    out += ["    " + " ".join(f"{{0x{a:X}, {n}, {s}, 0x{f:X}}}," for a, n, f, s in runs[i:i + 4])
            for i in range(0, len(runs), 4)]
    return out + ["};", f"#define {name}_N {len(runs)}", ""]


def _norm_tables(up: str, nm, g, code: str) -> list[str]:
    from vtts.frontend import latin, latin_norm
    from vtts.frontend.lexicons import load_words

    def reading(v):
        return (v, v) if isinstance(v, str) else v

    out = c_pairs(f"VTTS_{up}_ABBREV", [(k, nm.ABBREVIATIONS[k])
                                        for k in sorted(nm.ABBREVIATIONS, key=len, reverse=True)])
    out += [f"#define VTTS_{up}_DROP {c_str(latin_norm.DROP)}", ""]
    out += c_letters(f"VTTS_{up}_LETTERS", nm.LETTERS.items())
    out += c_list(f"VTTS_{up}_ACRONYM_WORDS", sorted(nm.ACRONYM_WORDS))
    units = sorted(nm.UNITS, key=len, reverse=True)  # the alternation order of the regexes
    if code == "tr":
        units = sorted([*nm.UNITS, *nm.SPEED], key=len, reverse=True)
        out += c_triples(f"VTTS_{up}_UNITS", [(k, nm.UNITS.get(k, ""), "speed" if k in nm.SPEED else "")
                                              for k in units])
    else:
        out += c_triples(f"VTTS_{up}_UNITS", [(k, *reading(nm.UNITS[k])) for k in units])
    cur = sorted(nm.CURRENCY, key=len, reverse=True)
    out += c_triples(f"VTTS_{up}_CURRENCY", [(k, *reading(nm.CURRENCY[k])) for k in cur])
    assert all(len(k) == 1 for k in nm.SYMBOLS)
    assert not any(k in v for v in nm.SYMBOLS.values() for k in nm.SYMBOLS)
    out += c_letters(f"VTTS_{up}_SYMBOLS", nm.SYMBOLS.items())
    out += [f"#define VTTS_{up}_COMMA {c_str(nm.MARK_WORDS[','])}",
            f"#define VTTS_{up}_PERIOD {c_str(nm.MARK_WORDS['.'])}", ""]
    out += c_list(f"VTTS_{up}_MONTHS", nm.MONTHS) + c_list(f"VTTS_{up}_DIGITS", nm.DIGITS)
    out += c_list(f"VTTS_{up}_NATIVE", sorted(load_words(code, "native")))
    out += c_list(f"VTTS_{up}_TABLE_KEYS", sorted(latin._table_keys(code)))
    out += [f"#define VTTS_{up}_OWN {c_str(latin.LATIN_PAIRS[code])}", ""]
    return out


# literal strings of normalize_it.py that vtts_text_it.c writes itself
IT_LITERALS = ('"zero"', '"meno "', '"mille"', '"mila"', '"cento"', '"tré"', 'f"un {one}"', "l'una",
               '" e {cardinal(mi)}"', "secondi", "per cento", "centesimo", "centesimi", "'primo'",
               '"treesimo"', '"esimo"', '"sei"', '" {cardinal(int(m.group(1)))} a {cardinal(int(m.group(2)))} "')


def italian_tables() -> list[str]:
    from vtts.frontend import phoneme_set
    from vtts.frontend.it import g2p_it as g
    from vtts.frontend.it import normalize_it as nm

    tset = phoneme_set.TOKENS_ITEN
    tok0 = phoneme_set.VOCAB_SIZE_V2
    out = HEAD + ["/* Italian front-end tables (token set it-en): src/vtts/frontend/it and lexicons/it. */",
                  "#ifndef VTTS_TEXT_IT_TABLES_H", "#define VTTS_TEXT_IT_TABLES_H", "#include <stdint.h>", "",
                  f"#define VTTS_ITEN_VOCAB {len(tset)}", f"#define VTTS_ITEN_TOK0 {tok0}", ""]
    out += c_list("VTTS_IT_TOKENS", [t.split(":", 1)[1] for t in tset[tok0:]])
    out += _norm_tables("IT", nm, g, "it")
    out += c_list("VTTS_IT_ONES", nm.ONES) + c_list("VTTS_IT_TENS", nm.TENS)
    out += c_list("VTTS_IT_ORD_SMALL", nm.ORD_SMALL) + c_list("VTTS_IT_NOT_COUNTED", sorted(nm.NOT_COUNTED))
    assert [x for x, _, _ in nm.SCALES] == [10 ** 12, 10 ** 9, 10 ** 6]
    out += c_pairs("VTTS_IT_SCALES", [(one, many) for _, one, many in nm.SCALES])
    src = Path(nm.__file__).read_text(encoding="utf-8")
    for lit in IT_LITERALS:  # strings written by vtts_text_it.c: each must appear in normalize_it.py
        assert lit in src, lit
    # g2p
    out += c_pairs("VTTS_IT_OVERRIDES", sorted(g.override_table().items(), key=lambda kv: kv[0].encode()))
    out += c_list("VTTS_IT_UNSTRESSED", sorted(g.UNSTRESSED, key=str.encode))
    out += c_list("VTTS_IT_ELIDED", sorted(g.ELIDED))
    out += [f"#define VTTS_IT_GRAVE {c_str(''.join(g.GRAVE))}", f"#define VTTS_IT_GRAVE_BASE {c_str(''.join(g.GRAVE.values()))}",
            f"#define VTTS_IT_ACUTE {c_str(''.join(g.ACUTE))}", f"#define VTTS_IT_ACUTE_BASE {c_str(''.join(g.ACUTE.values()))}",
            f"#define VTTS_IT_FRONT {c_str(g.FRONT)}", f"#define VTTS_IT_VOICED {c_str(g.VOICED)}", ""]
    out += c_list("VTTS_IT_IA_STEMS", g.IA_STEMS) + c_list("VTTS_IT_IA_ERIA_AFTER", g.IA_ERIA_AFTER)
    out += c_list("VTTS_IT_TEN_WORDS", g.TEN_WORDS) + c_list("VTTS_IT_ERE_STEMS", g.ERE_STEMS)
    assert set("abcdefghijklmnopqrstuvwxyz") <= g.LETTERS
    for c in range(0x80):
        assert g.fold(chr(c)) == (chr(c).lower() if chr(c).isalpha() else ""), c
    out += fold_runs("VTTS_IT_FOLD", g.fold)
    for attr in ("ONSETS", "CODAS", "FINALS", "DOUBLES"):
        out += c_list(f"VTTS_IT_{attr}", sorted(getattr(g, attr)))
    out += c_list("VTTS_IT_FOREIGN", g.FOREIGN) + c_pairs("VTTS_IT_DIGRAPHS", g.DIGRAPHS)
    return out + ["#endif", ""]


TR_LITERALS = ('"trilyon"', '"milyar"', '"milyon"', '"bin"', '"yüz"', '"eksi "', "saatte", "kilometre",
               " yüzde ", " ile ", '"artı"', '"dörd"', '"nc"', "(saat|Saat)")


def turkish_tables() -> list[str]:
    from vtts.frontend import phoneme_set
    from vtts.frontend.tr import g2p_tr as g
    from vtts.frontend.tr import normalize_tr as nm

    tset = phoneme_set.TOKENS_TREN
    tok0 = phoneme_set.VOCAB_SIZE_V2
    out = HEAD + ["/* Turkish front-end tables (token set tr-en): src/vtts/frontend/tr and lexicons/tr. */",
                  "#ifndef VTTS_TEXT_TR_TABLES_H", "#define VTTS_TEXT_TR_TABLES_H", "#include <stdint.h>", "",
                  f"#define VTTS_TREN_VOCAB {len(tset)}", f"#define VTTS_TREN_TOK0 {tok0}", ""]
    out += c_list("VTTS_TR_TOKENS", [t.split(":", 1)[1] for t in tset[tok0:]])
    out += _norm_tables("TR", nm, g, "tr")
    out += c_list("VTTS_TR_ONES", nm.ONES) + c_list("VTTS_TR_TENS", nm.TENS)
    out += c_pairs("VTTS_TR_CENTS", nm.CENTS.items())
    src = Path(nm.__file__).read_text(encoding="utf-8")
    for lit in TR_LITERALS:  # strings written by vtts_text_tr.c: each must appear in normalize_tr.py
        assert lit in src, lit
    gsrc = Path(g.__file__).read_text(encoding="utf-8")
    for lit in ('"dört"', '"d"', "ky", "gy", '"long"'):  # and in g2p_tr.py
        assert lit in gsrc, lit
    out += c_pairs("VTTS_TR_OVERRIDES", sorted(g.override_table().items(), key=lambda kv: kv[0].encode()))
    out += c_list("VTTS_TR_UNSTRESSED", sorted(g.UNSTRESSED))
    out += c_letters("VTTS_TR_PHONEME", g.PHONEME.items())
    out += [f"#define VTTS_TR_VOWELS {c_str(g.VOWELS)}", f"#define VTTS_TR_FRONT {c_str(g.FRONT)}",
            f"#define VTTS_TR_LONG {c_str(''.join(g.LONG_VOWELS))}",
            f"#define VTTS_TR_LONG_BASE {c_str(''.join(g.LONG_VOWELS.values()))}", ""]
    for c in range(0x80):
        want = chr(c).lower() if chr(c).isalpha() else ""
        if chr(c) == "I":
            want = "ı"
        assert g.fold(chr(c)) == want, c
    out += fold_runs("VTTS_TR_FOLD", g.fold)
    for attr in ("ONSETS", "FINALS"):
        out += c_list(f"VTTS_TR_{attr}", sorted(getattr(g, attr)))
    assert g.CODAS is g.FINALS
    out += c_list("VTTS_TR_FOREIGN", g.FOREIGN)
    from vtts.frontend import latin

    out += [f"#define VTTS_TR_SUFFIX_LETTERS {c_str(''.join(sorted(latin.SUFFIX_LETTERS)))}  /* latin.SUFFIX_LETTERS */", ""]
    return out + ["#endif", ""]


def write_all() -> None:
    for name, fn in (("vtts_text_it_tables.h", italian_tables), ("vtts_text_tr_tables.h", turkish_tables)):
        (SRC / name).write_text("\n".join(fn()), encoding="utf-8")
        print(f"wrote {SRC / name}")
